export default {
    async main({title = 'On this page', hn = 'h2', area = '.content-area'}, {
        ctx: { assetId },
        fns: { resolveMatrixAssetById }
    }) {
        try {
            const key = 'anchor_nav';
            const result = await resolveMatrixAssetById(assetId, ['metadata']);
            return `${
                result?.data?.metadata?.sidebar_items?.includes(key) ?
                `<span data-anchor-nav='${JSON.stringify({ title, hn, area })}'></span>` :
                `<span style="display:none;"> ${key}: disabled ${JSON.stringify(result ?? null)}</div>`
            }`;
        } catch (err) {
            return  `<span style="display:none;">${String(err)}</span>`;  
        }
    }
}